// The site: a landing page (src/pages/index.astro) at the root, the reference (Starlight, pages generated by `zil --docs`) at /docs/
// and the sandbox (a Svelte island) at /play/.
import { readFileSync } from "node:fs";
import starlight from "@astrojs/starlight";
import svelte from "@astrojs/svelte";
import { defineConfig } from "astro/config";

const sidebar = JSON.parse(readFileSync(new URL("./src/content/docs/sidebar.json", import.meta.url), "utf8"));
const fonts = "https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:ital,wght@0,400;0,500;1,400&family=IBM+Plex+Sans:wght@400;500;600&display=swap";

export default defineConfig({
  site: "https://zil.alexander-bui.com",
  outDir: "../site",
  integrations: [
    starlight({
      title: "zil",
      description: "A terse calculator and scripting language for units, dates and much more.",
      social: [{ icon: "github", label: "GitHub", href: "https://github.com/zbu1/zil" }],
      sidebar,
      customCss: ["./src/theme.css"],
      components: { SocialIcons: "./src/components/Nav.astro", MarkdownContent: "./src/components/Content.astro" },
      head: [
        { tag: "link", attrs: { rel: "preconnect", href: "https://fonts.gstatic.com", crossorigin: true } },
        { tag: "link", attrs: { rel: "stylesheet", href: fonts } },
        // Starlight picks up public/favicon.svg on its own.
        { tag: "link", attrs: { rel: "apple-touch-icon", href: "/apple-touch-icon.png" } },
      ],
    }),
    svelte(),
  ],
  vite: {
    // The sandbox lists ../examples; the wasm worker imports the wasm-bindgen output.
    server: { fs: { allow: [".."] } },
    worker: { format: "es" },
  },
});
